package com.finsightai.service;
import com.finsightai.model.AuditLog; import com.finsightai.repository.AuditLogRepository; import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import java.time.Instant;
@Service public class AuditService {private final AuditLogRepository repo; public AuditService(AuditLogRepository repo){this.repo=repo;} public void record(String action,String type,String id,String details){Authentication a=SecurityContextHolder.getContext().getAuthentication(); AuditLog l=new AuditLog(); l.setUsername(a==null||!a.isAuthenticated()?"SYSTEM":a.getName());l.setAction(action);l.setEntityType(type);l.setEntityId(id);l.setDetails(details);l.setTimestamp(Instant.now());repo.save(l);}}
